// #732f80 (6a9ff813) — TC-AV-01 (several statuses at once), TC-AV-02 (all 5 + uncheck all back to none).
// Changes the logged-in test account's availability; the after-hook always restores the initial value (checked via guest API).
import assert from 'node:assert/strict';
import { startDriver, byText, goTab, apiGet, USERS, IS_IOS } from '../lib/session.js';

const ME = IS_IOS ? USERS.ios : USERS.android;
// screen label → server code (availabilityStatus is a comma-separated string, null when nothing is selected)
const OPTIONS = [
  ['ייעוץ ראשוני טלפוני', 'phone_consult'],
  ['זמין לעבודה מיידית', 'immediate_work'],
  ['זמין לאספקת שירות באופן מיידי', 'immediate_service'], // seen in API 2026-10-26
  ['זמין בימים הקרובים', 'coming_days'],
  ['זמין בשעות הקרובות', 'coming_hours'],
];
const KNOWN = OPTIONS.map(([, c]) => c);
const labelOf = (code) => {
  const o = OPTIONS.find(([, c]) => c === code);
  if (!o) throw new Error(`unknown availability code: ${code}`);
  return o[0];
};

async function serverState() {
  const { status, body } = await apiGet(`/user/${ME.id}`);
  assert.equal(status, 200);
  const codes = body.availabilityStatus ? String(body.availabilityStatus).split(',').map((s) => s.trim()).filter(Boolean) : [];
  return { codes, raw: body.availabilityStatus, contacts: [...(body.contactMethods || [])].sort() };
}

describe('Availability screen multi-select #732f80 @ios @android @data', function () {
  let d; let initial;
  before(async () => { initial = await serverState(); d = await startDriver(); });

  async function openScreen() {
    await goTab(d, 'זמינות');
    await (await byText(d, 'הגדרת זמינות')).waitForDisplayed({ timeout: 15000 });
    await (await byText(d, 'רגילה')).click();
    await (await byText(d, OPTIONS[0][0])).waitForDisplayed({ timeout: 5000 });
  }
  async function toggle(labels) { for (const l of labels) await (await byText(d, l)).click(); }
  async function save(expectCount) {
    const b = await byText(d, 'עדכן זמינות');
    await b.scrollIntoView?.().catch(() => {});
    await b.click();
    let s;
    await d.waitUntil(async () => { s = await serverState(); return s.codes.length === expectCount; },
      { timeout: 20000, interval: 1500, timeoutMsg: `server did not get ${expectCount} statuses` });
    return s;
  }
  /** Uncheck whatever the server says is selected and save → none. */
  async function clearAll() {
    const cur = await serverState();
    if (!cur.codes.length) return cur;
    await openScreen();
    await toggle(cur.codes.map(labelOf));
    return save(0);
  }

  after(async () => {
    if (!d) return;
    try {
      await clearAll();
      if (initial.codes.length) { await openScreen(); await toggle(initial.codes.map(labelOf)); await save(initial.codes.length); }
      const fin = await serverState();
      assert.deepEqual([...fin.codes].sort(), [...initial.codes].sort(), 'availability restored');
      assert.deepEqual(fin.contacts, initial.contacts, 'contact methods untouched');
    } finally { await d.deleteSession(); }
  });

  it('TC-AV-01: two statuses at once — second does not cancel the first; saved to server', async () => {
    await clearAll();
    await openScreen();
    await toggle([OPTIONS[0][0], OPTIONS[1][0]]);
    const s = await save(2);
    assert.deepEqual([...s.codes].sort(), ['immediate_work', 'phone_consult']);
    assert.deepEqual(s.contacts, initial.contacts, 'contact methods not changed by saving statuses');
  });

  it('TC-AV-02: all 5 statuses together, then uncheck all → none (null)', async () => {
    await clearAll();
    await openScreen();
    await toggle(OPTIONS.map(([l]) => l));
    const all = await save(5);
    assert.equal(new Set(all.codes).size, 5, 'five distinct statuses');
    for (const c of KNOWN) assert.ok(all.codes.includes(c), `status ${c} saved`);
    const none = await clearAll();
    assert.equal(none.raw ?? null, null, 'no statuses → availabilityStatus is null');
  });
});
